fn setup(){assert!(!r("source").exists());assert_eq!(read(format!("{B}/review.json"))["review_passed"],true);let original_pins=read(format!("{B}/build-pins.json"));let mut pins=BTreeMap::new();let prefix=format!("{B}/source/");let mut count=0;for(p,h)in original_pins.as_object().unwrap(){if let Some(relative)=p.strip_prefix(&prefix){assert_eq!(hash(p),h.as_str().unwrap());let to=r("source").join(relative);fs::create_dir_all(to.parent().unwrap()).unwrap();fs::copy(p,&to).unwrap();pin(&mut pins,&to);count+=1;}}assert_eq!(count,179);let m=read(M);let mut exact=0;for(p,h)in m["source_files_sha256"].as_object().unwrap(){assert_eq!(hash(Path::new(Z).join(p)),h.as_str().unwrap());if hash(r("source").join(p))==h.as_str().unwrap(){exact+=1;}}assert_eq!(exact,170);fs::copy(format!("{B}/source-audit.json"),r("parent-source-audit.json")).unwrap();save(r("source-audit.json"),&json!({"source_files":179,"all179exact_to_parent":true,"accepted_originals":176,"originals_exact":170,"all176recover_via_parent_edits":true,"all_field_sources_exact":true,"compiler_profile_only_addition_to_parent":true,"parent_gate_stays_false":true,"production_changed":false}));for d in["raw","build-raw"]{fs::create_dir(r(d)).unwrap();}let plain=fs::read_to_string(format!("{B}/candidate-flags.txt")).unwrap();for(label,flags)in[("control",plain.clone()),("generate",format!("{plain} -C profile-generate={} -C llvm-args=-instrprof-atomic-counter-update-all",r("raw").display())),("candidate",format!("{plain} -C profile-use={} -C llvm-args=-pgo-warn-missing-function",r("merged.profdata").display()))]{fs::write(r(format!("{label}-flags.txt")),flags).unwrap();pin(&mut pins,r(format!("{label}-flags.txt")));}for p in[M,LLVM]{pin(&mut pins,p);}for f in["bootstrap.rs","native.rs","native-helper","setup.rs","design.md","train-driver.rs","driver.rs","support/perf.rs","source-audit.json","parent-source-audit.json"]{pin(&mut pins,r(f));}let plan=steps("generate",false);assert_eq!(plan.len(),3);save(r("build-pins.json"),&json!(pins));save(r("build-plan.json"),&json!({"version":1,"source_pins":r("build-pins.json"),"steps":plan}));println!("Prepared3GENsteps;179exact parent sources/170acceptedoriginalsexact/all176recover; no historical profile or repeated test");}
fn prepare_use(){assert!(!r("use-plan.json").exists());let a=read(r("training-audit.json"));assert_eq!(a["passed"],true);assert_eq!(a["SDK_prove_count"],99);assert_eq!(a["proof_ledger"],30052);let mut pins:BTreeMap<String,String>=serde_json::from_value(read(r("build-pins.json"))).unwrap();for(p,h)in&pins{assert_eq!(hash(p),*h);}for(p,h)in a["pins"].as_object().unwrap(){assert_eq!(hash(p),h.as_str().unwrap());pin(&mut pins,p);}for p in["merged.profdata","training-audit.json"]{pin(&mut pins,r(p));}let plan=steps("candidate",true);assert_eq!(plan.len(),8);save(r("use-pins.json"),&json!(pins));save(r("use-plan.json"),&json!({"version":1,"source_pins":r("use-pins.json"),"steps":plan}));println!("Prepared8USEsteps:35field-once+bothmodes128core8prover+coherentbuild/freeze/SDKlink; no timing or adoption");}
